/* bat.h — battery voltage (spec §7.10). Device layer.
 * ADC1 is not generated by CubeMX yet: until HAL_ADC_MODULE_ENABLED is on, the pack reads as
 * absent (bench supply) and nothing is sampled. */
#ifndef BAT_H
#define BAT_H

#include "main.h"
#include "units.h"

/* Init only; hadc1 is ADC_HandleTypeDef* (void* so the header builds without the ADC module).
 * Takes the first reading. ST_NODEV if there is no ADC. */
st_t  bat_init(void *hadc1);
void  bat_service(void);     /* S_FAST: every 20 ms read the previous conversion, start the next */
float bat_v(void);           /* filtered pack voltage [V], 0 if absent                           */
bool  bat_present(void);
bool  bat_low(void);         /* cut-off condition currently true                                 */

#endif
